alter table public.tasks add column if not exists goal_context_version integer; create or replace function public.set_task_goal_context_version() returns trigger language plpgsql set search_path to 'public' as $f$ begin if new.goal_id is not null and new.goal_context_version is null then select context_version into new.goal_context_version from public.goals where id=new.goal_id; end if; return new; end; $f$; drop trigger if exists tasks_set_goal_context_version on public.tasks; create trigger tasks_set_goal_context_version before insert on public.tasks for each row execute function public.set_task_goal_context_version();